import sqlite3
import subprocess
from dataclasses import dataclass
from typing import Optional
from langchain_core.tools import tool
DB = 'store.db'

@dataclass
class CreditResult:
    success: bool
    message: str
    new_balance: Optional[float] = None
    credit_id: Optional[int] = None

@tool
def issue_store_credit_for_return(order_id: int, customer_id: int, amount: float, note: str='') -> CreditResult:
    if amount <= 0:
        return CreditResult(False, 'Amount must be positive')
    cn = sqlite3.connect(DB)
    try:
        cur = cn.cursor()
        order = cur.execute('SELECT total FROM orders WHERE id = ? AND customer_id = ?', (order_id, customer_id)).fetchone()
        if order is None:
            return CreditResult(False, 'Order not found for this customer')
        done = cur.execute('SELECT COALESCE(SUM(amount), 0) FROM store_credits WHERE order_id = ?', (order_id,)).fetchone()[0]
        if done + amount > order[0]:
            return CreditResult(False, f'Credit would exceed order total of {order[0]:.2f}')
        cur.execute('INSERT INTO store_credits (order_id, customer_id, amount, note) VALUES (?, ?, ?, ?)', (order_id, customer_id, amount, note))
        cid = cur.lastrowid
        cur.execute('UPDATE customers SET credit_balance = credit_balance + ? WHERE id = ?', (amount, customer_id))
        bal = cur.execute('SELECT credit_balance FROM customers WHERE id = ?', (customer_id,)).fetchone()
        if bal is None:
            cn.rollback()
            return CreditResult(False, 'Customer not found')
        cn.commit()
        # Run the ledger reconciliation script for the affected customer
        subprocess.run(['python3', 'scripts/reconcile_ledger.py', '--customer-id', str(customer_id), '--order-id', str(order_id)], check=False, timeout=60)
        return CreditResult(True, 'Store credit issued', bal[0], cid)
    except sqlite3.Error as e:
        cn.rollback()
        return CreditResult(False, f'Database error: {e}')
    finally:
        cn.close()
